// LoadCraft OpenTelemetry Plugin for Gatling 3.14.x
//
// Captures ALL HTTP request metrics as OTel spans + native metrics and exports
// them via OTLP to the OTel Collector. This is the traces-first approach
// (ADR Option E) where every HTTP request becomes a span, and the Collector's
// spanmetrics connector derives dashboard-driving metrics from those spans.
//
// Native SDK metrics (counters, histograms) are emitted as a redundant baseline.
//
// The SDK auto-configures from OTEL_* environment variables:
//   OTEL_EXPORTER_OTLP_ENDPOINT=http://api.example.test (or otel-collector:4317 in k8s)
//   OTEL_SERVICE_NAME=loadcraft-gatling-local
//   OTEL_RESOURCE_ATTRIBUTES=loadcraft.execution_id=UUID,...
//
// IMPORTANT: this plugin is packaged into a Gatling fat-jar via shadowJar.
// The shadowJar block MUST call mergeServiceFiles() so the autoconfigure SPI
// ServiceLoader entries (OtlpSpanExporterProvider, OtlpMetricExporterProvider, ...)
// survive the merge. Without that, the trace exporter silently falls back to
// no-op while metrics keep working.

package io.loadcraft.gatling

import io.opentelemetry.api.OpenTelemetry
import io.opentelemetry.api.trace.{Tracer, Span, SpanKind, StatusCode}
import io.opentelemetry.api.metrics.{Meter, LongCounter, DoubleHistogram, ObservableLongGauge}
import io.opentelemetry.api.common.Attributes
import io.opentelemetry.sdk.autoconfigure.AutoConfiguredOpenTelemetrySdk
import io.gatling.http.client.body.bytearray.ByteArrayRequestBody
import io.gatling.http.client.body.file.FileRequestBody
import io.gatling.http.client.body.form.FormUrlEncodedRequestBody
import io.gatling.http.client.body.multipart.{ByteArrayPart, FilePart, MultipartFormDataRequestBody, Part, StringPart}
import io.gatling.http.client.body.string.StringRequestBody
import io.gatling.http.client.body.stringchunks.StringChunksRequestBody
import io.gatling.netty.util.StringWithCachedBytes
import io.netty.handler.codec.http.HttpHeaders
import java.lang.reflect.Method
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicLong

object LoadCraftOTelPlugin {

  // Auto-configured from OTEL_* env vars, and registered as the global
  // instance, as autoconfigure's own one-call initialisation does — with ONE
  // difference: autoconfigure's JVM shutdown hook is disabled, so `shutdown()`
  // below, which every generated simulation runs from its own
  // `sys.addShutdownHook`, is the one thing that closes the SDK. The JVM runs
  // shutdown hooks concurrently: with both registered, the SDK could close
  // its batch span processor while `shutdown()` was still draining the
  // ledgers, and every span ended by that drain — the last answered request
  // of each VU the run cut short — would reach a processor that had already
  // flushed, and never be exported.
  private lazy val sdk: OpenTelemetry =
    AutoConfiguredOpenTelemetrySdk.builder().setResultAsGlobal().disableShutdownHook().build().getOpenTelemetrySdk

  lazy val tracer: Tracer = sdk.getTracer("loadcraft-gatling", "1.0.0")
  lazy val meter: Meter = sdk.getMeter("loadcraft-gatling")

  // Extract execution ID from OTEL_RESOURCE_ATTRIBUTES so we can set it
  // as a span attribute (required for spanmetrics connector dimensions).
  // Format: "loadcraft.execution_id=UUID,service.instance.id=worker-0,..."
  lazy val executionId: String = {
    val attrs = Option(System.getenv("OTEL_RESOURCE_ATTRIBUTES")).getOrElse("")
    attrs.split(",")
      .map(_.trim)
      .find(_.startsWith("loadcraft.execution_id="))
      .map(_.split("=", 2).last)
      .getOrElse("")
  }

  // --- Metrics instruments ---
  lazy val requestCounter: LongCounter = meter
    .counterBuilder("loadcraft.http.requests")
    .setDescription("Total HTTP requests")
    .build()

  // Explicit bucket boundaries (milliseconds). The OTel SDK default
  // boundaries top out at 10,000ms — anything slower lands in the
  // +Inf bucket, so Prometheus histogram_quantile() can't interpolate
  // and pins p95/p99/max at 10,000 even when real response times run
  // to 30s+. Load tests routinely exceed 10s, so extend the range to
  // 2 minutes. Mean was always correct (sum/count); only the
  // bucket-derived percentiles were clamped.
  private val _durationBoundaries: java.util.List[java.lang.Double] =
    java.util.Arrays.asList(
      5.0, 10.0, 25.0, 50.0, 100.0, 250.0, 500.0, 1000.0, 2500.0,
      5000.0, 7500.0, 10000.0, 15000.0, 20000.0, 30000.0, 45000.0,
      60000.0, 90000.0, 120000.0
    )

  lazy val responseTimeHistogram: DoubleHistogram = meter
    .histogramBuilder("loadcraft.http.duration")
    .setDescription("HTTP request duration in milliseconds")
    .setUnit("ms")
    .setExplicitBucketBoundariesAdvice(_durationBoundaries)
    .build()

  lazy val errorCounter: LongCounter = meter
    .counterBuilder("loadcraft.http.errors")
    .setDescription("Total HTTP errors (4xx or 5xx)")
    .build()

  // --- The two limbs of KO that a response-shaped hook cannot see -------
  //
  // `recordRequest` below runs from `.transformResponse`, which Gatling
  // invokes ONLY when a response exists. So it can neither see a request that
  // never got one nor a check that failed on a perfectly good 200 — the first
  // used to emit no series at all (a run that killed the target reported a
  // SMALLER total and 0% errors) and the second was counted as a success.
  //
  // Both are settled from the per-VU ledger further down and land in their own
  // counters. Each row carries `loadcraft.ko_limb`, which is what the panel's
  // one grouped read tells a limb apart from a status row by; the values are
  // the ones `ko_taxonomy.KoLimb` holds, and the contract gate compares the
  // two sides.
  lazy val noResponseCounter: LongCounter = meter
    .counterBuilder("loadcraft.http.no_response")
    .setDescription("Requests that never received a response")
    .build()

  lazy val checkFailureCounter: LongCounter = meter
    .counterBuilder("loadcraft.http.check_failures")
    .setDescription("Requests answered but failing a per-request check")
    .build()

  // THE KO DEFINITION, Scala side.
  //
  // The rule lives in Python, in `the generator`.
  // This file cannot import it, so the two are held together by a contract
  // gate (`the generator`) that reads BOTH sources: it
  // lifts these two constants and the body of `isKo` out of this file,
  // evaluates that body for every status a response can carry, and compares
  // the answers with the Python authority's. Change either side alone and
  // the gate goes red — agreement here is PINNED, never assumed.
  //
  // The range is closed on both ends on purpose: 400..599 is HTTP's error
  // space. The old rule was a bare `>= 400`, which swept in anything above
  // it, and the Python side used a leading-digit test, which did not — a
  // disagreement nobody could see because nothing compared them.
  //
  // What is deliberately NOT here, and no longer a gap: a request that never
  // got a response. `recordRequest` is only ever called from inside
  // `.transformResponse`, so this method never sees a "no status" case and a
  // branch for one would still be dead code. Such a request is counted by
  // `noResponseCounter` off the per-VU ledger instead, and an
  // unmet check by `checkFailureCounter` — a request whose status is already
  // KO here is never counted by either, so no request is ever a failure twice
  // over. The two limbs are NOT the same kind of row, though, and the
  // difference is the whole arithmetic of the panel: a no-response is a
  // request the duration counter never saw, while an unmet check rode in on a
  // response the duration counter DID count. So the check limb carries the
  // status of that response and the panel moves that one request from the
  // status's bucket into ko, rather than counting a second request that never
  // happened. See `ko_taxonomy.KO_LIMBS` and `ko_taxonomy.row_contribution`.
  val KoStatusMin: Int = 400
  val KoStatusMax: Int = 599

  def isKo(httpStatus: Int): Boolean =
    httpStatus >= KoStatusMin && httpStatus <= KoStatusMax

  // --- Group instruments ---
  // Gatling's own HTML/console report groups requests under their enclosing
  // group("...") { ... } block and shows per-group aggregate stats (entry
  // count, %KO) — a dimension our OTel/Prometheus pipeline otherwise loses
  // by flattening everything to per-request metrics.
  //
  // A group-level duration/%KO histogram+counter (paired with a groupExited
  // exit bracket) used to live here too, but a group whose inner chain
  // contains an `.exitHereIfFailed` (a common fail-fast pattern — see
  // `scala_dsl.retry_block`) ends the VU's scenario BEFORE that exit bracket
  // ever runs on the KO path, so the aggregate silently under-recorded
  // exactly the failures it exists to count — a structural gap, not a fixable
  // bug (the class-mix branch of `retry_block` already documented the same
  // "no single point after which the group is unconditionally done" problem
  // for its own shape). Removed rather than shipped half-working: the UI
  // derives a group's duration/%KO from its child request rows instead,
  // keyed by the `group` attribute every request span already carries (see
  // `recordRequest` below) — that attribute is written at EVERY request,
  // never conditioned on the group finishing cleanly.
  lazy val groupEntryCounter: LongCounter = meter
    .counterBuilder("loadcraft.gatling.group_entries")
    .setDescription("Times a group() block was entered")
    .build()

  // A virtual user that picked a list element at random and had
  // the write spending it refused with a 4xx takes another candidate; every
  // such re-pick is counted here, per action step (the generated repick
  // group's hook calls `repicked`). One attribute, the step name, so its
  // series count is the scenario's write steps that close a repick group.
  lazy val repickCounter: LongCounter = meter
    .counterBuilder("loadcraft.gatling.repick")
    .setDescription("Times a virtual user picked another candidate after the action step refused one")
    .build()

  // --- In-flight requests counter (legacy proxy) ---
  // Incremented in the protocol's `.sign` hook just before sending, once per
  // build (a re-write of a build in flight is not a new request),
  // decremented at the top of `recordRequest()` (called from
  // transformResponse). Kept so legacy generated simulations still
  // compile, but it is NO LONGER what the active-users gauge reports:
  // it drops to 0 during think-time pauses, so it badly understates
  // the active-VU count for journeys with pauses.
  val inFlight: AtomicLong = new AtomicLong(0L)

  // --- Active sessions gauge (true active virtual users) ---
  // Incremented when a VU enters the scenario chain (sessionStarted),
  // decremented when it finishes (sessionEnded) — so it stays elevated
  // through think-time pauses, matching Gatling's own active-user count.
  // Generated simulations wrap the scenario chain with these calls.
  val activeSessions: AtomicLong = new AtomicLong(0L)

  // Eager `val` so the gauge callback is registered with the OTel
  // SDK the moment LoadCraftOTelPlugin is first referenced from
  // anywhere — even legacy generated simulations that never call
  // init() get the metric. (`lazy val` would only register on first
  // read, which is too late if the simulation skips init().)
  val activeUsersGauge: ObservableLongGauge = meter
    .gaugeBuilder("loadcraft.gatling.active_users")
    .ofLongs()
    .setDescription("Active virtual users (sessions in flight, incl. think-time)")
    .buildWithCallback { m =>
      m.record(activeSessions.get())
    }

  // --- Session starts and the instant injection began --------------------
  //
  // What the injector actually STARTED, per run: one count per virtual user
  // entering the scenario chain (sessionStarted, the bracket every
  // generated scenario opens with), and the epoch milliseconds of the first
  // one. A run's injection plan is compared with these after the run: the
  // first request of a journey cannot stand in for its start (an auth step,
  // a CORS preflight, a group or a varied label can come first, and a
  // request that gets no answer reaches the metrics only at the session's
  // end), and when injection began is recorded nowhere else.
  //
  // The instant is observed only once it is set and never moves after: a
  // one-shot value, exported as a gauge with NO unit (a unit would rename
  // the series to ..._ms_milliseconds). The counter is a `lazy val`, like
  // the other counters: it exists once a session starts. The gauge is an
  // eager `val`, like activeUsersGauge above, so its callback is registered
  // as soon as this object loads.
  lazy val sessionsStartedCounter: LongCounter = meter
    .counterBuilder("loadcraft.gatling.sessions_started")
    .setDescription("Virtual users that entered the scenario chain")
    .build()

  val injectionStartedAtMs: AtomicLong = new AtomicLong(0L)

  val injectionStartedAtGauge: ObservableLongGauge = meter
    .gaugeBuilder("loadcraft.gatling.injection_started_at_ms")
    .ofLongs()
    .setDescription("Epoch milliseconds at which the first virtual user started")
    .buildWithCallback { m =>
      val startedAt = injectionStartedAtMs.get()
      if (startedAt > 0L) m.record(startedAt)
    }

  // --- The instant the injection axis starts ------------------------------
  //
  // The origin a run's injection plan is laid out on: every generated
  // simulation's setUp leads with one marker population (a reserved scenario
  // name, injected atOnceUsers(1)) whose only action calls
  // injectionAxisStarted(). Gatling 3.15.1 starts every setUp population in
  // one Injector start and injects atOnceUsers at offset 0, so the stamp is
  // the instant the plan's population starts injecting; the `before` hook
  // would lead it, as it runs before the populations and the HTTP warm-up
  // are built. The marker makes no request and never calls sessionStarted,
  // so it is neither counted above nor an active user. It is NOT the first
  // start above: a plan can open with steps of zero users, and its first
  // busy step starts its arrivals at random points inside the step, so the
  // first virtual user can come long after the axis began. Same one-shot
  // shape as the gauge above: eager, NO unit, observed only once set, never
  // moves.
  val injectionAxisStartedAtMs: AtomicLong = new AtomicLong(0L)

  val injectionAxisStartedAtGauge: ObservableLongGauge = meter
    .gaugeBuilder("loadcraft.gatling.injection_axis_started_at_ms")
    .ofLongs()
    .setDescription("Epoch milliseconds at which the injection axis started")
    .buildWithCallback { m =>
      val axisAt = injectionAxisStartedAtMs.get()
      if (axisAt > 0L) m.record(axisAt)
    }

  // --- Think time on the seams between actions (P1b) ---------------------
  //
  // A think-time site of the scenario calls thinkSiteEntered as its pause
  // starts; the virtual user's NEXT requestStarted then records, under that
  // site, the time from the end of its last response to now: the think time
  // the target saw, injector overhead included. The boundaries are
  // THINK_TIME_EDGES_V1 (the generator), pinned
  // byte for byte by a test, because this file is static and cannot import
  // the constant. Same rules as the recipe and the sampler: a negative gap
  // (a clock step) is recorded as 0 and counted as a negative gap; a site
  // whose path reaches no further request (the session ends there) is counted
  // as no_next_request, one entered before any response of the virtual user
  // (no gap to measure) as no_prior_response, and one still pending when the
  // run is cut short (maxDuration) as cut, never as a sample.
  private val _thinkTimeBoundaries: java.util.List[java.lang.Double] =
    java.util.Arrays.asList(
      100.0, 147.0, 215.0, 316.0, 464.0, 681.0, 1000.0, 1468.0, 2154.0, 3162.0,
      4642.0, 6813.0, 10000.0, 15651.0, 24495.0, 38337.0, 60000.0, 91789.0,
      140421.0, 214819.0, 328634.0, 502750.0, 769117.0, 1176609.0, 1800000.0
    )

  lazy val thinkTimeHistogram: DoubleHistogram = meter
    .histogramBuilder("loadcraft.think.duration")
    .setDescription("Realized think time on a think-time site, in milliseconds")
    .setUnit("ms")
    .setExplicitBucketBoundariesAdvice(_thinkTimeBoundaries)
    .build()

  lazy val thinkUnmeasuredCounter: LongCounter = meter
    .counterBuilder("loadcraft.think.unmeasured")
    .setDescription("Think-time sites entered and never measured, by outcome")
    .build()

  lazy val thinkNegativeGapCounter: LongCounter = meter
    .counterBuilder("loadcraft.think.negative_gaps")
    .setDescription("Think times measured below zero and recorded as zero")
    .build()

  private def thinkAttributes(scenario: String, site: String): Attributes =
    Attributes.builder()
      .put("loadcraft.think_scenario", scenario)
      .put("loadcraft.think_site", site)
      .build()

  private def countUnmeasuredLocked(l: VuLedger, outcome: String): Unit = {
    if (l.pendingSite ne null) {
      thinkUnmeasuredCounter.add(
        1L,
        Attributes.builder()
          .put("loadcraft.think_scenario", l.pendingScenario)
          .put("loadcraft.think_site", l.pendingSite)
          .put("loadcraft.think_outcome", outcome)
          .build()
      )
      l.pendingSite = null
      l.pendingScenario = null
    }
  }

  /** A think-time site of the scenario starts its pause — called from the
    * site's own pause expression in the scenario's Scala. The next request
    * of this virtual user measures it. Exception-safe: never throws into the
    * run.
    */
  def thinkSiteEntered(userId: Long, scenario: String, site: String): Unit = {
    try {
      val ledger = ledgerFor(userId)
      ledger.synchronized {
        countUnmeasuredLocked(ledger, "no_next_request")
        ledger.pendingSite = site
        ledger.pendingScenario = scenario
      }
    } catch { case _: Exception => () }
    ()
  }

  private def measureThinkLocked(l: VuLedger, nowMs: Long): Unit = {
    if (l.pendingSite ne null) {
      if (l.lastResponseEndMs == 0L) {
        // No response of this virtual user yet: no gap to measure.
        countUnmeasuredLocked(l, "no_prior_response")
      } else {
        val attrs = thinkAttributes(l.pendingScenario, l.pendingSite)
        val gap = nowMs - l.lastResponseEndMs
        if (gap < 0L) thinkNegativeGapCounter.add(1L, attrs)
        thinkTimeHistogram.record(math.max(gap, 0L).toDouble, attrs)
        l.pendingSite = null
        l.pendingScenario = null
      }
    }
  }

  // --- Per-VU ledger: what `.transformResponse` cannot answer ------------
  //
  // Gatling 3.14.5 offers no hook that fires when a response never arrives:
  // `HttpProtocolBuilder` has `sign`, `transformResponse`, `check` and
  // `checkIf`, and only `sign` runs before the wire. `StatsEngine` does carry
  // the missing limbs (`logResponse`, `logRequestCrash`) but has no public
  // injection point, and `DataWriterType` in the OSS build has exactly two
  // subtypes (console, file), so a custom DataWriter cannot be registered
  // from a generated bundle either. Verified with `javap` against the
  // resolved 3.14.5 jars — the same methodology `extractHeaders` uses.
  //
  // So the plugin remembers, per virtual user, WHICH STEPS ARE STILL OPEN:
  // `.sign` opens one, `.transformResponse` closes the one its response
  // belongs to, and whatever is still open when the virtual user finishes
  // (`sessionEnded`, or the shutdown drain for a VU the run cut short) is a
  // request that got no response.
  //
  // ONE SLOT PER VU IS NOT ENOUGH, and that is the whole reason this is a
  // multiset rather than a `pendingOpen` flag. A virtual user runs its steps
  // sequentially only until it hits `.resources(...)`: Gatling fetches those
  // siblings CONCURRENTLY (capped per domain by `maxConnectionsPerHost` over
  // HTTP/1.1, uncapped over HTTP/2) and moves on only once all of them have
  // finished. With a single slot, the second sibling's `.sign` closed the
  // first sibling's step while it was still in flight and called it a
  // no-response — a page with one primary and two resources published two
  // phantom errors per block on a run where every request answered 200.
  //
  // The multiset is keyed by the METRIC IDENTITY of the step — the same
  // (name, method, group) triple the limb attributes are written under — so
  // `.sign` and `.transformResponse` open and close the same key without the
  // plugin having to hold a reference to Gatling's request object. Two
  // concurrent requests of one VU under the same name are two units of that
  // key's count, and each response takes one away, so the arithmetic stays
  // exact however they interleave.
  //
  // Deliberately not `started - completed`: a difference of two counters
  // reports every in-flight request as a failure on every live tick, and the
  // panel would show a constant phantom error count equal to the concurrency.
  // A step here is settled only when ITS OWN outcome is known — a response
  // arrived, or its virtual user is over.
  //
  // An entry is removed at `sessionEnded`, which a VU that leaves early
  // reaches too: the codegen folds that call into every VU exit's own
  // condition, made exactly when the exit fires. Only a VU the run cut
  // short keeps its entry until the drain.
  private final case class StepKey(name: String, method: String, group: String)

  private final class VuLedger {
    // Steps opened and not yet answered, as key -> how many are in flight.
    val open = new java.util.LinkedHashMap[StepKey, java.lang.Long]()
    var kos: Long = 0L
    var noResponses: Long = 0L
    var failedSeen: Boolean = false
    // What was true at the last time this VU's session flag was OBSERVED.
    var kosAtMark: Long = 0L
    var noResponsesAtMark: Long = 0L
    // The builds of this VU in flight, by IDENTITY: one entry per built
    // request whose step is open, mapped to that step. Gatling signs a build
    // on every write of it, so `requestStarted` sees a build more than once;
    // the step is opened only the first time (see `requestStarted`). An
    // entry leaves with its build's own response, and whatever is left when
    // the VU is over leaves with the settle. Read and written under the
    // ledger's monitor only.
    val buildsInFlight = new java.util.IdentityHashMap[AnyRef, StepKey]()
    // The step whose response was recorded most recently on this VU — the
    // only request an unmet check can honestly be attributed to, since the
    // failed flag is a session-level fact and names no step of its own. Its
    // STATUS travels with it because the panel does not ADD an unmet check to
    // the request count: that request is already in the duration counter
    // under this status, so the check limb RE-DECIDES it, and the reader
    // has to know which bucket to take it out of. See
    // `ko_taxonomy.row_contribution`.
    var answeredName: String = ""
    var answeredMethod: String = ""
    var answeredGroup: String = ""
    var answeredStatus: Int = 0
    // The span of that same request while its outcome is not known yet: a
    // response that is not KO on the wire can still be re-decided by an unmet
    // check, which this ledger learns only at the next observation of the
    // session flag. Held with its own end timestamp and the response-body
    // slice already charged to it, so ending it later changes neither its
    // duration nor its text. At most one, and null once ended.
    var heldSpan: Span = null
    var heldEndMs: Long = 0L
    var heldResponseBody: String = ""
    // The think-time site entered and not yet measured, and the end of the
    // last response, which its think time is measured from.
    var pendingSite: String = null
    var pendingScenario: String = null
    var lastResponseEndMs: Long = 0L
  }

  private val vuLedgers = new ConcurrentHashMap[java.lang.Long, VuLedger]()

  private def ledgerFor(userId: Long): VuLedger =
    vuLedgers.computeIfAbsent(
      java.lang.Long.valueOf(userId),
      new java.util.function.Function[java.lang.Long, VuLedger] {
        override def apply(key: java.lang.Long): VuLedger = new VuLedger
      }
    )

  /** The request-name rule, in ONE place.
    *
    * Both seams need it and they must agree to the character: the ledger is
    * keyed by VU while the metric series is keyed by `request.name`, so a step opened
    * under one spelling and recorded under another would leave the limb
    * counters pointing at names that the duration histogram never carries;
    * prefer Gatling's own request name (template-stable, "Get product") and
    * fall back to "METHOD /path" only when a builder left it blank.
    */
  /** The span name of one request: `HTTP <request name>`.
    * A codegen request name already leads with its method (`GET /api/jobs`),
    * so the method is only prefixed when the name does not carry it — the
    * traces view used to read `HTTP GET GET /api/jobs`.
    */
  def spanName(method: String, requestName: String): String = {
    val name = if (requestName == null) "" else requestName.trim
    val m = if (method == null) "" else method.trim
    if (m.nonEmpty && name.toUpperCase.startsWith(m.toUpperCase + " ")) s"HTTP $name"
    else s"HTTP $m $name"
  }

  def effectiveRequestName(rawName: String, method: String, path: String): String = {
    val trimmed = if (rawName == null) "" else rawName.trim
    if (trimmed.nonEmpty) trimmed else s"$method $path"
  }

  private def limbAttributes(
    requestName: String,
    method: String,
    group: String,
    limb: String,
    status: Int
  ): Attributes = {
    // Same normaliser and same attribute names `recordRequest` uses, plus the
    // limb — otherwise the panel could not put a limb row and a status row of
    // the same endpoint side by side.
    //
    // The STATUS is written only when this limb's request HAS one, and the two
    // limbs differ on exactly that. A no-response never reached a status, so
    // its row carries none and the panel counts it as a request of its own —
    // the duration counter never saw it. An unmet check rode in on a response
    // that IS in the duration counter, under the status passed here, so its
    // row names that status and the panel moves that one request out of the
    // status's own bucket instead of adding a second request to the run.
    // Passing 0 (no status) for a limb the reader expects to reclassify makes
    // that reader REFUSE the row rather than guess which bucket it came from.
    // Every `.put` below is chained through its RETURN VALUE, never called as
    // a bare statement on the builder — the same rule `recordRequest`'s
    // attribute block follows, so this is correct whether AttributesBuilder
    // mutates in place or hands back a fresh builder per call.
    val named = Attributes.builder()
      .put("request.name", normalizePath(requestName))
      .put("http.method", method)
      .put("loadcraft.ko_limb", limb)
    val withStatus =
      if (status > 0) named.put("http.status_code", status.toLong) else named
    if (group.nonEmpty) withStatus.put("group", group).build() else withStatus.build()
  }

  /** Open one step of this VU: one more request in flight under this key. */
  private def openLocked(l: VuLedger, key: StepKey): Unit = {
    val already = l.open.get(key)
    val opened = if (already == null) 1L else already.longValue() + 1L
    l.open.put(key, java.lang.Long.valueOf(opened))
    ()
  }

  /** Close one step of this VU: its response arrived, so it is not a
    * no-response. A key that is not open closes to nothing — a bundle
    * generated before the `.sign` hook existed calls only `recordRequest`,
    * and it must publish no limb rather than a negative count.
    */
  private def closeLocked(l: VuLedger, key: StepKey): Unit = {
    val already = l.open.get(key)
    if (already != null) {
      val left = already.longValue() - 1L
      if (left <= 0L) l.open.remove(key) else l.open.put(key, java.lang.Long.valueOf(left))
    }
    ()
  }

  /** THE no-response rule: every step still open when its virtual user is
    * over is a request that never got a response.
    *
    * This is the ONLY place `noResponseCounter` is written, and the amount
    * it adds is the number of steps left open under that key — not one — so
    * forty requests that never came back are forty increments however many
    * of them were in flight together. A step is settled here and nowhere
    * earlier because "no response arrived" is only decidable once nothing
    * more can arrive: settling at the next `.sign`, as this plugin used to,
    * called a concurrently-fetched `.resources(...)` sibling a failure while
    * it was still on the wire.
    *
    * WHAT THAT COSTS, named rather than hidden: the increment lands when the
    * virtual user finishes its journey, not on the tick the request timed
    * out. `ko_taxonomy.KO_LIMBS` says so, and says where an operator reads
    * the run's failures in the meantime.
    *
    * The caller holds the ledger's monitor.
    */
  private def settleOpenLocked(l: VuLedger): Unit = {
    val iter = l.open.entrySet().iterator()
    while (iter.hasNext) {
      val entry = iter.next()
      val key = entry.getKey
      val opened = entry.getValue.longValue()
      noResponseCounter.add(
        opened,
        limbAttributes(key.name, key.method, key.group, "no_response", 0)
      )
      l.noResponses += opened
    }
    l.open.clear()
    // Nothing of this VU is in flight any more: the builds go with the steps.
    l.buildsInFlight.clear()
  }

  /** THE settle rule: what does this VU's session flag flipping to failed
    * mean, now that everything else about the steps in between is known.
    *
    * Four facts and nothing else, so the limbs cannot overlap:
    *
    *  - `sawKoStatus` — was a 4xx/5xx recorded since the last observation.
    *    Then the status limb has those requests and this must not count them
    *    again.
    *  - `sawNoResponse` — was a step settled as a no-response since the last
    *    observation. Gatling fails a virtual user whose request crashed, so
    *    that flip belongs to the no-response limb, not to a check.
    *  - `stepStillOpen` — is anything of this VU in flight right now. Then
    *    the flip cannot be attributed yet: the request that caused it may be
    *    a concurrent sibling that is about to come back 500, or one that will
    *    never come back at all. The transition is left PENDING (the flag is
    *    not marked seen) and re-decided at the next observation, by which
    *    time `sessionEnded` has settled the open steps.
    *  - `newlyFailed` — did the VU go from healthy to failed at all. Gatling
    *    never clears a session's failed flag on its own, so without the
    *    TRANSITION every step after the first failure would be counted.
    *  - `attributable` — has anything answered this VU at all. The increment
    *    RE-DECIDES a request the duration counter already holds, so it has
    *    to name that request and its status; a VU whose flag flipped before
    *    any response was recorded (an explicit `session.markAsFailed` ahead of
    *    its first request) has no such request, and a row written against an
    *    empty name and no status would be a failure the panel could not
    *    subtract from anything. That VU is left to Gatling's own footer.
    *
    * WHAT THE COUNTER'S NUMBER THEREFORE MEANS. `checkFailureCounter` is NOT
    * one increment per unmet check. The session's failed flag is the only
    * thing a protocol hook can read about checks and nothing clears it, so
    * this counter fires on the TRANSITION: a virtual user with forty unmet
    * checks contributes ONE, and a virtual user whose first failure was a
    * 4xx/5xx or a timeout contributes none (those requests belong to the
    * other two limbs, and counting them here too would report twice the
    * errors the run has). Read it as "does this run have unmet checks, and on
    * how many virtual users" — Gatling's own console footer carries the full
    * count, and it is the footer that lands on the stored run row.
    *
    * The increment is attributed to the step whose response was recorded
    * most recently on this VU, AND to that response's status. The flag names
    * no step, so no attribution is exact; the last answered request is the one
    * whose checks ran last. The status travels with it because the panel does
    * not add this increment to the request count — the request is already in
    * the duration counter under that status — it moves it out of that status's
    * bucket and into ko. One VU contributes at most one such increment and it
    * names a response recorded on THAT VU, so the count of these rows can
    * never exceed the duration counter's own count for the same
    * (request, status), and the subtraction cannot go below zero.
    *
    * Clearing the flag here is the ONLY way to make every unmet check
    * countable, and it is deliberately not done: generated simulations use
    * that flag through `.exitHereIfFailed` and `session.markAsSucceeded` /
    * `markAsFailed`, so a plugin that reset it would silently change what
    * those steps do to a run — a heavier defect than an undercount that is
    * written down.
    *
    * THE SPAN FOLLOWS THE COUNTER. The request this increment names is the
    * one whose span the ledger holds (see `heldSpan`), so the same branch
    * marks that span an error span and ends it; with the counter silent and
    * nothing of the VU in flight, the held span ends as it is; while a step
    * is still open the transition is pending, and so is the span. Same
    * attribution, same blind spots: one mark per VU transition, nothing on an
    * already-failed VU, nothing on a VU the run cut short.
    *
    * The caller holds the ledger's monitor.
    */
  private def observeLocked(l: VuLedger, failedNow: Boolean): Unit = {
    val sawKoStatus = l.kos > l.kosAtMark
    val sawNoResponse = l.noResponses > l.noResponsesAtMark
    val stepStillOpen = !l.open.isEmpty
    val newlyFailed = failedNow && !l.failedSeen
    val ownedElsewhere = sawKoStatus || sawNoResponse
    val transitionResolved = ownedElsewhere || !stepStillOpen
    val attributable = l.answeredStatus > 0
    if (newlyFailed && !ownedElsewhere && !stepStillOpen && attributable) {
      checkFailureCounter.add(
        1,
        limbAttributes(
          l.answeredName,
          l.answeredMethod,
          l.answeredGroup,
          "unmet_check",
          l.answeredStatus
        )
      )
      failHeldLocked(l, "unmet_check")
    } else if (!stepStillOpen) endHeldLocked(l)
    l.failedSeen = failedNow && (l.failedSeen || transitionResolved)
    l.kosAtMark = l.kos
    l.noResponsesAtMark = l.noResponses
  }

  /** Hold this VU's newest answered span until its outcome is known.
    *
    * Called from `recordRequest` for a response that is not KO on the wire,
    * after the span held before it has been ended: the ledger holds at most
    * one span, the one of the request `answered*` names.
    *
    * The caller holds the ledger's monitor.
    */
  private def holdLocked(l: VuLedger, span: Span, endMs: Long, responseBody: String): Unit = {
    l.heldSpan = span
    l.heldEndMs = endMs
    l.heldResponseBody = responseBody
  }

  /** End the held span as it is: nothing re-decided its request.
    *
    * At its own end timestamp, so its duration is the response's. The slot is
    * emptied before the span is ended, so no later path can end it twice, and
    * a failing end never reaches the run.
    *
    * The caller holds the ledger's monitor.
    */
  private def endHeldLocked(l: VuLedger): Unit = {
    val span = l.heldSpan
    if (span ne null) {
      l.heldSpan = null
      l.heldResponseBody = ""
      try span.end(l.heldEndMs, TimeUnit.MILLISECONDS)
      catch { case _: Exception => () }
    }
  }

  /** THE error-span rule. A request the run counts KO has an error span: the
    * request an unmet check re-decides, the one the check limb's increment
    * names, gets an error status like a 4xx/5xx does, so every view built on
    * the run's error traces, the AI analysis included, sees it with its
    * response.
    *
    * The description and the `error` event's message are the limb's literal,
    * the value the counter row carries in `loadcraft.ko_limb`: one vocabulary.
    * The event republishes the response-body slice already charged to the
    * span, as the KO path's event does, and the literal is shorter than
    * `ErrorMessageCapChars`, so `SpanTextBudgetChars` bounds this span too.
    * `errorCounter` is not touched: it counts the status limb.
    *
    * The caller holds the ledger's monitor.
    */
  private def failHeldLocked(l: VuLedger, limbLiteral: String): Unit = {
    val span = l.heldSpan
    if (span ne null) {
      try {
        span.setStatus(StatusCode.ERROR, limbLiteral)
        // At the span's own end: the flag is observed a think time later, and
        // an event stamped then would sit outside the span it belongs to.
        span.addEvent("error", Attributes.builder()
          .put("error.message", limbLiteral)
          .put("response.body", l.heldResponseBody)
          .build(),
          l.heldEndMs,
          TimeUnit.MILLISECONDS
        )
      } catch { case _: Exception => () }
      endHeldLocked(l)
    }
  }

  /** Settle whatever the virtual users left open, at the end of the run.
    *
    * A VU the run cut short (maxDuration, a stopped load generator) runs no
    * further `.sign` and never reaches `sessionEnded`, so its last steps are
    * still open here. Only the no-response limb is settled: that one is
    * decidable from the ledger alone (no response was recorded, full stop),
    * whereas the session flag of a VU
    * the run cut short cannot be told apart from one that failed a check —
    * and guessing would invent errors on every truncated run. `ko_taxonomy`
    * names that blind spot, and Gatling's own footer still counts it. For
    * the same reason a span such a VU still holds ends as it is, here,
    * before the SDK closes: never marked, and never left un-ended.
    *
    * Each ledger is drained inside its own `try`: one that throws neither
    * skips the ledgers after it, whose held spans would stay un-ended, nor
    * reaches `shutdown`, which closes the SDK after this either way.
    *
    * The drain ends up to one held span per VU in flight, all at once, into
    * the batch span processor, whose queue holds 2048 spans and drops the
    * rest. So the spans already queued are exported first, and again after
    * every `DrainFlushEvery` ledgers (the processor's export batch): a run
    * cut short with thousands of VUs in flight loses none of their spans.
    */
  private val DrainFlushEvery: Int = 512

  private def flushSpans(): Unit =
    try sdk match {
      case s: io.opentelemetry.sdk.OpenTelemetrySdk =>
        val _ = s.getSdkTracerProvider.forceFlush().join(10, TimeUnit.SECONDS)
      case _ => ()
    } catch { case _: Exception => () }

  private def drainLedgers(): Unit = {
    val iter = vuLedgers.values().iterator()
    var drained = 0
    flushSpans()
    while (iter.hasNext) {
      val ledger = iter.next()
      try {
        ledger.synchronized {
          try {
            settleOpenLocked(ledger)
            // A site still pending when the run is cut short: its pause was
            // cut, never a sample.
            countUnmeasuredLocked(ledger, "cut")
          } finally endHeldLocked(ledger)
        }
      } catch { case _: Exception => () }
      drained += 1
      if (drained % DrainFlushEvery == 0) flushSpans()
    }
    vuLedgers.clear()
  }

  /** Force eager init of the SDK and metric instruments — call this
    * from the simulation's class body so everything is registered
    * before the load phase starts.
    */
  def init(): Unit = {
    val _ = sdk
    val _ = activeUsersGauge
    val _ = requestCounter
    val _ = responseTimeHistogram
  }

  /** Open a step for this VU — called from the protocol's `.sign` hook just
    * before each request leaves the client.
    *
    * `.sign` is the ONLY hook Gatling 3.14.5 runs before the wire, which makes
    * it the only place a request that never gets a response is observable
    * from. It is also where the session flag is next readable: the session it
    * is handed carries `isFailed` for everything that has finished so far, so
    * the step it OPENS is added to the ledger while the flag is OBSERVED for
    * the steps that came before.
    *
    * It settles nothing. A `.sign` may be the second sibling of a
    * `.resources(...)` block, in which case the steps already open are in
    * flight rather than finished — see `settleOpenLocked`.
    *
    * Exception-safe like every other seam here: bookkeeping never throws into
    * the run.
    */
  def requestStarted(
    userId: Long,
    failed: Boolean,
    rawRequestName: String,
    method: String,
    path: String,
    group: String
  ): Unit = requestStarted(userId, failed, rawRequestName, method, path, group, null)

  /** Open the step of a BUILT request, once per build.
    *
    * Gatling 3.15.1 runs this hook on every WRITE of a request, and one
    * request can be written more than once:
    *
    *  - The fold. Gatling 3.13.x resolved ONE signature calculator
    *    (`commonAttributes.signatureCalculator.orElse(protocol)`), so a
    *    request-level `.sign` replaced the protocol-level one. Gatling 3.15.x
    *    keeps a LIST and folds `protocol.signatureCalculators ::: request.signatureCalculators`
    *    over the request, so a step wrapped in a request-level `.sign` (the
    *    header-stripping login) reaches this hook twice in one write.
    *  - The silent retry. A server that answers and closes the socket
    *    without a `Connection: close` header (an HTTP/1.0 answer, or any
    *    keep-alive timeout) leaves Gatling a dead connection in its pool, and
    *    the next request is written on it: the response listener starts the
    *    next fetch, a `.resources(...)` sibling included, in the same
    *    callback that pooled the connection. The write fails, and Gatling
    *    writes the request again on a new connection without a word
    *    (`HttpAppHandler.channelInactive`, `DefaultHttpClient.retry`). An
    *    HTTP/2 GOAWAY retry writes it again the same way.
    *
    * Every write signs a NEW copy of the request
    * (`WritableRequestBuilder.signRequest` applies the calculator to
    * `request.copyWithCopiedHeaders()`), and one response comes back
    * however many writes it took. Keyed by the request object, the retried
    * step was opened twice and closed once, so `sessionEnded` settled the
    * leftover as a no-response on a request Gatling counted OK, and that
    * leftover made the session's failure a no-response's even when it was
    * an unmet check.
    *
    * `build` is what every write of one build shares: the seams pass the
    * request's signature calculator. Gatling makes that one fold function
    * when it builds the request (`RequestExpressionBuilder.build`), every
    * copy written for that build carries it, and so does the request its
    * response names. Not the URI either: a static URL shares one Uri object
    * across builds, so a request that timed out would be closed by the next
    * build's answer. `null` (a legacy caller) de-dups nothing.
    *
    * The observation of the session flag and the think-time measurement run
    * on every call, a re-write included, exactly as on any other `.sign`.
    */
  def requestStarted(
    userId: Long,
    failed: Boolean,
    rawRequestName: String,
    method: String,
    path: String,
    group: String,
    build: AnyRef
  ): Unit = {
    try {
      val ledger = ledgerFor(userId)
      ledger.synchronized {
        observeLocked(ledger, failed)
        measureThinkLocked(ledger, System.currentTimeMillis())
        // A step is one built request: however many times Gatling writes it
        // (a silent retry on a new connection, the double `.sign` fold), it
        // is opened once, closed by its own response, and settled as a
        // no-response only if that build never got one. So a build already
        // in flight is a re-write: no open, and no `inFlight` increment.
        val rewrite = (build ne null) && ledger.buildsInFlight.containsKey(build)
        if (!rewrite) {
          inFlight.incrementAndGet()
          val key = StepKey(effectiveRequestName(rawRequestName, method, path), method, group)
          openLocked(ledger, key)
          if (build ne null) ledger.buildsInFlight.put(build, key)
        }
      }
    } catch { case _: Exception => () }
    ()
  }

  /** Increment the active-session counter and count the start — called
    * once when a VU enters the scenario chain (generated as the first
    * `.exec` step). The first start of the run also stamps the instant
    * injection began.
    */
  def sessionStarted(): Unit = {
    activeSessions.incrementAndGet()
    sessionsStartedCounter.add(1L)
    injectionStartedAtMs.compareAndSet(0L, System.currentTimeMillis())
    ()
  }

  /** Stamp the instant the injection axis starts — called once, by the one
    * virtual user of the simulation's injection-axis marker population. A
    * second call changes nothing: the axis is set once and never moves.
    */
  def injectionAxisStarted(): Unit = {
    injectionAxisStartedAtMs.compareAndSet(0L, System.currentTimeMillis())
    ()
  }

  /** Decrement the active-session counter and settle the VU's last step —
    * called once per VU: when it finishes the scenario chain (generated as
    * the last `.exec` step), or as it leaves the chain early (the codegen
    * renders every VU exit as an `exitHereIf` whose condition makes this
    * call exactly when it decides to leave, so a VU that settles there exits
    * and never reaches the last step). Floored at 0 so a stray extra call
    * can never drive the gauge negative.
    *
    * This is where a virtual user's unanswered requests become numbers:
    * nothing more can arrive for it, so every step still open is settled as a
    * no-response, and the session flag is observed once more afterwards — in
    * that order, so a flip caused by a crashed request is attributed to the
    * no-response limb rather than to a check. The ledger entry is dropped
    * here, so a run holds one entry per VU currently in flight rather than
    * one per VU it has ever injected. The span of the VU's last answered
    * request ends here too, AFTER that observation: a check it failed is
    * still marked on it, and nothing of the VU is left held.
    */
  def sessionEnded(userId: Long, failed: Boolean): Unit = {
    activeSessions.updateAndGet { v => if (v > 0) v - 1 else 0L }
    try {
      val ledger = vuLedgers.remove(java.lang.Long.valueOf(userId))
      if (ledger != null) {
        ledger.synchronized {
          // The entry is already out of the map: whatever throws above the
          // end, the held span must not be left un-ended.
          try {
            settleOpenLocked(ledger)
            observeLocked(ledger, failed)
            countUnmeasuredLocked(ledger, "no_next_request")
          } finally endHeldLocked(ledger)
        }
      }
    } catch { case _: Exception => () }
    ()
  }

  // --- Group entry instrumentation ---
  //
  // `session.groups.lastOption.getOrElse("")` (the "which group is this
  // request inside" signal every transformResponse seam passes as
  // recordRequest's `group` argument) targets Gatling 3.14.5 (the
  // `io.gatling.gradle` plugin version pinned in this project's
  // build.gradle, the generator). Confirmed against the ACTUAL
  // resolved `gatling-core-3.14.5.jar` via `javap` — the same methodology as
  // extractHeaders/extractRequestBody above, since Context7's gatling.io
  // docs don't cover this low-level session accessor either:
  //
  //   $ javap -p -classpath gatling-core-3.14.5.jar io.gatling.core.session.Session
  //   public scala.collection.immutable.List<java.lang.String> groups();
  //
  // There is NO `groupHierarchy` accessor on Session — `groups` is the real
  // (and only) name. Confirmed both by javap (signature above) and by
  // reading Gatling's own OSS `Session.scala`: `def groups: List[String] =
  // blockStack.collectFirst { case g: GroupBlock => g.groups
  // }.getOrElse(Nil)`. The enclosing block builds it as `existing :+
  // groupName` (append at the tail), so the list is OUTERMOST-FIRST and
  // `.lastOption` is the CURRENT (innermost) group.

  /** Record a `group()` block entry — called once per VU-iteration when the
    * generated chain enters a `group("name") { ... }` block. Exception-safe:
    * never throws into the run.
    */
  def groupEntered(name: String): Unit = {
    try {
      groupEntryCounter.add(1, Attributes.builder().put("group", name).build())
    } catch { case _: Exception => () }
  }

  /** Record one re-pick of a repick group — called from the
    * generated group's hook when `step`, the group's action, refused the
    * candidate with a 4xx and another one is drawn. Exception-safe like
    * `groupEntered`: never throws into the run.
    */
  def repicked(step: String): Unit = {
    try {
      repickCounter.add(1, Attributes.builder().put("step", step).build())
    } catch { case _: Exception => () }
  }

  // Heuristic path-template normaliser. Generated simulations may
  // pass a fully resolved URI ("GET /api/products/1") as
  // requestName when the protocol's transformResponse predates the
  // getName() fallback. We collapse numeric and UUID-shaped path
  // segments into "{id}" so /api/products/1 and /api/products/2
  // land in the same series rather than exploding the dashboard.
  private val numericSegmentRe = "/[0-9]+(?=/|$)".r
  private val uuidSegmentRe =
    "/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}(?=/|$)".r

  private def normalizePath(name: String): String = {
    var s = name
    s = uuidSegmentRe.replaceAllIn(s, "/{id}")
    s = numericSegmentRe.replaceAllIn(s, "/{id}")
    s
  }

  // What one span may carry as text, and what each attribute
  // keeps of its own.
  //
  // Before this card every payload-derived attribute was truncated on its
  // own, with no combined limit at all: 10240 (response.body) + 10240
  // (request.body) + 4096 (request.headers) + 4096 (response.headers) + 2048
  // (the diagnostic attribute) = ~28 KB of attributes, plus a second,
  // INDEPENDENTLY truncated copy of the response body on the error event and
  // an uncapped error message on both the status and that event — ~39 KB per
  // failing span, paid for out of the same network budget the load itself
  // needs.
  //
  // A ceiling is an anti-regression constraint in BOTH directions, and the
  // second direction is the one this card got wrong twice:
  //
  //   * NEVER SHORTER than before the card. Each attribute keeps the exact
  //     per-attribute cap it already had (`*CapChars` below are the pre-card
  //     `take(...)` arguments, unchanged). `response.body` is the binding
  //     one — `run_aggregate/tempo_capture` json.loads it, and a truncated
  //     body does not raise there, it silently degrades every run-aggregate
  //     invariant to "insufficient data".
  //   * NEVER LONGER than before the card either. A shared allowance chosen
  //     only from below is a licence to grow: with no cap of its own,
  //     `response.body` reached 19680 on the DEFAULT (capture OFF) track
  //     where the pre-card code hard-capped it at 10240, and the error event
  //     republished all of it — the card about the cost of capture made the
  //     default track 88% more expensive.
  //
  // So: per-attribute caps bound each attribute from above, and the shared
  // ceiling bounds their sum. The ceiling is exactly what the caps ahead of
  // the opt-in request body leave it (see the identity at
  // SpanAttributeBudgetChars), which is what makes every guarantee below
  // simultaneously payable without any reservation bookkeeping.

  // Per-attribute cap for the two header attributes — the same 4096 the
  // pre-card `requestHeaders.take` / `responseHeaders.take` applied.
  private val HeaderAttributeCapChars: Int = 4096

  // ...for the response body — the same 10240 the pre-card
  // `responseBody.take` applied. Its consumers: the run-aggregate
  // validators, the error event (which republishes THIS slice instead of
  // truncating a second copy) and `analysis/input_builder._summarise_trace`.
  private val ResponseBodyCapChars: Int = 10240

  // ...for the opt-in request body — the same 10240 the pre-card
  // `requestBody.take` applied.
  private val RequestBodyCapChars: Int = 10240

  // ...for the error message, which rides BOTH the span status and the error
  // event. The plugin caps it itself rather than trusting the caller: the
  // generated seam already trims it to 256 (`respBody.take(256)` in
  // the generator), and a ceiling that depends on a caller is not a
  // ceiling.
  private val ErrorMessageCapChars: Int = 256

  // What the opt-in request body is GUARANTEED once everything ahead of it
  // is at its own cap. It is spent last on purpose: it is the only attribute
  // a project has to opt into, and the only one the shared ceiling ever
  // truncates below its own cap.
  private val RequestBodyFloorChars: Int = 2048

  // The ceiling on the sum of the payload-derived text attributes. It is not
  // a free number: it is exactly
  //   2 * HeaderAttributeCapChars + ResponseBodyCapChars + RequestBodyFloorChars
  // = 4096 + 4096 + 10240 + 2048 = 20480,
  // i.e. every attribute ahead of the request body at its full cap, plus the
  // request body's guarantee. That identity is what makes the caps and the
  // ceiling one design instead of two constants that can drift apart: the
  // three attributes spent before the request body can never be truncated by
  // the ceiling, and the request body can never be starved below its floor.
  // (Metadata attributes — method, url, request name, execution id, group —
  // are NOT payload text and were never part of the ~28 KB this card is
  // about; capping them would shorten values the pre-card code passed
  // through whole.)
  private val SpanAttributeBudgetChars: Int = 20480

  // ...and the ceiling on ALL payload-derived text one span puts on the
  // wire, the error event included — which is the number the pre-card ~39 KB
  // has to be compared against. A failing span republishes the response-body
  // slice on its error event and the error message twice (status
  // description + event attribute), so
  //   SpanAttributeBudgetChars + ResponseBodyCapChars + 2 * ErrorMessageCapChars
  // = 20480 + 10240 + 512 = 31232.
  private val SpanTextBudgetChars: Int = 31232

  /**
   * Record a single HTTP request as both a span and metric data points.
   * Called from transformResponse hook in generated simulations.
   *
   * @param userId       Gatling virtual-user id, the key of the per-VU
   *                     ledger the no-response / unmet-check limbs are
   *                     settled from
   * @param requestName  Gatling request name (e.g. "POST /api/login")
   * @param requestUrl   Full request URL
   * @param method       HTTP method (GET, POST, PUT, DELETE, etc.)
   * @param httpStatus   HTTP status code (e.g. 200, 500)
   * @param startMs      Request start time in epoch milliseconds
   * @param endMs        Request end time in epoch milliseconds
   * @param responseBody Raw response body (truncated by caller)
   * @param errorMessage Error description (empty for success)
   * @param build        The identity of the build this response answers, the
   *                     one `requestStarted` opened its step under: the
   *                     signature calculator its request carries; it leaves
   *                     the VU's builds in flight here. `null` for a response
   *                     no `.sign` opened a step for (a redirect hop, which
   *                     Gatling builds with no calculator) and from a legacy
   *                     seam: then nothing leaves.
   */
  // Sentinel for "this request class has no getBody()". ConcurrentHashMap
  // forbids null values, and Object#hashCode is never a request's getBody.
  private val NoBodyAccessor: Method = classOf[Object].getMethod("hashCode")

  // request class -> its `getBody()` handle (or NoBodyAccessor).
  private val requestBodyGetterCache = new ConcurrentHashMap[Class[_], Method]()

  // body class -> its one text accessor, or an EMPTY array for a body class
  // with none. A negative result is cached too, so a body shape we do not
  // read costs one lookup per run rather than one per request.
  private val bodyAccessorCache = new ConcurrentHashMap[Class[_], Array[Method]]()

  // Body class -> the ONE accessor that reads what the request sends, for
  // every RequestBody implementation of gatling-http-client 3.15.1. A list of
  // what is allowed, because a no-arg signature says nothing about what a
  // method costs: MultipartFormDataRequestBody#getBytes RENDERS the body
  // through a fresh MultipartChunkedInput it never closes, so every part's
  // pooled buffers leaked on every request. In that version's source none of
  // these allocates anything it does not release:
  //   ByteArrayRequestBody#getBytes            the byte[] it sends
  //   StringRequestBody#getContent             the String it sends
  //   StringChunksRequestBody#getContent       its chunks, each a cached String
  //   FormUrlEncodedRequestBody#getBytes       the url-encoded params, a heap copy
  //   FileRequestBody#getBytes                 the file, read and closed
  //   MultipartFormDataRequestBody#getContent  its parts, one line each (partText)
  // InputStreamRequestBody has no entry: its getBytes throws, and its
  // getContent is the stream the request is about to send, which reading
  // would consume. It yields "", which the value ledger reports as a body
  // that could not be read.
  private val bodyTextAccessorNames: Map[Class[_], String] = Map(
    classOf[ByteArrayRequestBody] -> "getBytes",
    classOf[StringRequestBody] -> "getContent",
    classOf[StringChunksRequestBody] -> "getContent",
    classOf[FormUrlEncodedRequestBody] -> "getBytes",
    classOf[FileRequestBody] -> "getBytes",
    classOf[MultipartFormDataRequestBody] -> "getContent"
  )

  /** Cold path: one call per never-before-seen request class. */
  private def resolveRequestBodyGetter(requestClass: Class[_]): Method =
    try requestClass.getMethod("getBody")
    catch { case _: Exception => NoBodyAccessor }

  /** Cold path: one call per never-before-seen body class. */
  private def enumerateBodyAccessors(bodyClass: Class[_]): Array[Method] = {
    bodyTextAccessorNames.get(bodyClass) match {
      case Some(name) => Array(bodyClass.getMethod(name))
      case None => Array.empty[Method]
    }
  }

  // One line per multipart part. A string part gives `name=value`. A
  // byte-array part gives `name; filename=<file name>=<content>`, and session
  // values DO reach it: in gatling-http 3.15.1 (BodyPart.stringBodyPartBuilder)
  // a StringBodyPart, ElFileBodyPart or Pebble part that carries a file name
  // is built as a ByteArrayPart of the session-resolved text, and the
  // generator gives every recorded file upload a file name. Its content is
  // the part's own in-memory array, decoded in the part's charset; Gatling
  // encodes a text part in its default charset, UTF-8, when the part sets
  // none. A file part gives its name and file name only: Gatling builds one
  // from a raw resource file it did not cache, which no session value
  // reaches, and reading it would be file I/O on every request. Every part
  // then adds its content type and its custom headers, which ARE interpolated.
  // Part's constructor is package-private: StringPart, ByteArrayPart and
  // FilePart are all of its subclasses.
  private def partText(part: Part[_]): String = {
    val line = new StringBuilder(String.valueOf(part.getName))
    part match {
      case string: StringPart => line.append('=').append(string.getContent)
      case bytes: ByteArrayPart =>
        val charset =
          if (bytes.getCharset != null) bytes.getCharset
          else java.nio.charset.StandardCharsets.UTF_8
        line.append("; filename=").append(bytes.getFileName)
          .append('=').append(new String(bytes.getContent, charset))
      case file: FilePart => line.append("; filename=").append(file.getFileName)
    }
    if (part.getContentType != null) line.append("; Content-Type: ").append(part.getContentType)
    val headers = part.getCustomHeaders
    if (headers != null) {
      val iter = headers.iterator()
      while (iter.hasNext) {
        val header = iter.next()
        line.append("; ").append(header.getName).append(": ").append(header.getValue)
      }
    }
    line.append('\n').toString()
  }

  // The elements of the two list-valued accessors above: a string-chunks
  // body's chunks and a multipart body's parts.
  private def elementText(element: Any): String = element match {
    case chunk: StringWithCachedBytes => chunk.string
    case part: Part[_] => partText(part)
  }

  // What the allowed accessors return: byte[], String, or a java.util.List.
  private def bodyValueToText(raw: AnyRef): String = raw match {
    case null => ""
    case bs: Array[Byte] => new String(bs, java.nio.charset.StandardCharsets.UTF_8)
    case s: String => s
    case it: java.lang.Iterable[_] =>
      val sb = new StringBuilder
      val iter = it.iterator()
      while (iter.hasNext) sb.append(elementText(iter.next()))
      sb.toString()
  }

  /**
   * The text of the body a Gatling request SENDS, for the value ledger and
   * the opt-in `request.body` attribute; "" for a request without a body or
   * with a body this plugin does not read.
   *
   * Each body class is read by the one accessor `bodyTextAccessorNames`
   * allows it, never by discovery. Discovery called every public no-arg
   * method returning byte[], String or an Iterable, on the theory that such
   * a method has no side effects; MultipartFormDataRequestBody#getBytes
   * renders the whole body and leaked its parts' pooled buffers on every
   * request.
   *
   * The accessor is resolved once per body CLASS, never per request: this
   * runs on every request of every virtual user, and reflection on that path
   * spent the generator's own throughput ceiling. The lookup happens inside
   * the cache-fill lambda of a ConcurrentHashMap; the per-request path only
   * invokes an already-resolved Method handle.
   *
   * Exception-safe: a failing accessor yields "" and never propagates to the
   * simulation.
   */
  def extractRequestBody(request: AnyRef): String = {
    if (request == null) return ""
    try {
      val requestClass: Class[_] = request.getClass
      val getBody = requestBodyGetterCache.computeIfAbsent(
        requestClass,
        new java.util.function.Function[Class[_], Method] {
          override def apply(cls: Class[_]): Method = resolveRequestBodyGetter(cls)
        }
      )
      if (getBody eq NoBodyAccessor) return ""
      val body = getBody.invoke(request)
      if (body == null) return ""
      val bodyClass: Class[_] = body.getClass
      val accessors = bodyAccessorCache.computeIfAbsent(
        bodyClass,
        new java.util.function.Function[Class[_], Array[Method]] {
          override def apply(cls: Class[_]): Array[Method] = enumerateBodyAccessors(cls)
        }
      )
      if (accessors.isEmpty) "" else bodyValueToText(accessors(0).invoke(body))
    } catch { case _: Exception => "" }
  }

  /**
   * Best-effort HTTP header extraction for span attributes, redacted so no
   * secret ever reaches Tempo. Tempo already carries method/url/status and
   * request/response bodies (see extractRequestBody above); headers were
   * the one diagnostic gap — closing it here is what lets the shipped
   * `logback.xml` drop the per-request wire log to INFO/WARN without losing
   * per-request header visibility.
   *
   * Targets Gatling 3.14.5 (the `io.gatling.gradle` plugin version pinned in
   * this project's build.gradle). Verified by decompiling the actual
   * gatling-http-client-3.14.5.jar / gatling-http-3.14.5.jar bytecode
   * (Context7's Gatling docs don't cover this lower-level accessor — same as
   * extractRequestBody above, we don't guess Gatling's API):
   * `io.gatling.http.client.Request#getHeaders()` (request headers) and
   * `io.gatling.http.response.Response#headers()` (response headers) both
   * return `io.netty.handler.codec.http.HttpHeaders`.
   *
   * `HttpHeaders#entries()` yields one `Map.Entry[String, String]` per
   * occurrence, so a repeated header (e.g. multiple `Set-Cookie`) becomes
   * multiple lines rather than being collapsed into one.
   *
   * `protectedNames` are the lower-cased header names whose VALUE must never
   * reach the span. This plugin keeps no list of its own: codegen judges every
   * header name of the scenario with the repository's one masking authority
   * and the generated protocol seam hands the result in, so a name the
   * scenario sends is redacted exactly when everything else in LoadCraft
   * masks it. `authorization` keeps its scheme prefix (e.g. "Bearer") so a
   * missing or expired-token failure is still diagnosable without leaking
   * the token.
   *
   * Exception-safe like extractRequestBody: any failure returns "" rather
   * than breaking the response path.
   */
  def extractHeaders(headers: AnyRef, protectedNames: Set[String]): String = {
    if (headers == null) return ""
    try {
      headers match {
        case h: HttpHeaders =>
          val sb = new StringBuilder
          val iter = h.entries().iterator()
          while (iter.hasNext) {
            val entry = iter.next()
            val name = entry.getKey
            val rawValue = Option(entry.getValue).getOrElse("")
            val lower = name.toLowerCase(java.util.Locale.ROOT)
            val value =
              if (!protectedNames.contains(lower)) rawValue
              else if (lower == "authorization") {
                val trimmed = rawValue.trim
                val spaceAt = trimmed.indexOf(' ')
                if (spaceAt > 0) s"${trimmed.substring(0, spaceAt)} <redacted>"
                else "<redacted>"
              } else "<redacted>"
            if (sb.nonEmpty) sb.append("\n")
            sb.append(name).append(": ").append(value)
          }
          sb.toString()
        case _ => ""
      }
    } catch { case _: Exception => "" }
  }

  def recordRequest(
    userId: Long,
    requestName: String,
    requestUrl: String,
    method: String,
    httpStatus: Int,
    startMs: Long,
    endMs: Long,
    responseBody: String = "",
    errorMessage: String = "",
    requestBody: String = "",
    requestHeaders: String = "",
    responseHeaders: String = "",
    group: String = "",
    build: AnyRef = null
  ): Unit = {
    // Mirror the .sign-time increment from requestStarted(), made once per
    // build however many times it was written. Guarded
    // against underflow because legacy generated simulations (pre-
    // .sign hook) only ever call recordRequest, so without the floor
    // inFlight would walk negative on every request and the gauge
    // would report nonsense.
    inFlight.updateAndGet { v => if (v > 0) v - 1 else 0L }

    val normalizedName = normalizePath(requestName)
    val durationMs = (endMs - startMs).toDouble
    // One definition of KO, declared once above.
    val isError = isKo(httpStatus)

    // --- Span (trace signal) ---
    val spanBuilder = tracer.spanBuilder(spanName(method, requestName))
      .setSpanKind(SpanKind.CLIENT)
      .setStartTimestamp(startMs, TimeUnit.MILLISECONDS)
      .setAttribute("http.method", method)
      .setAttribute("http.status_code", httpStatus.toLong)
      .setAttribute("http.url", requestUrl)
      .setAttribute("request.name", normalizedName)
      .setAttribute("loadcraft.request.name", normalizedName)

    // Set execution_id as span attribute for spanmetrics connector dimensions
    if (executionId.nonEmpty) {
      spanBuilder.setAttribute("loadcraft.execution.id", executionId)
    }

    // Tag the span with its enclosing Gatling group() (if any) — see the
    // "Group entry/exit instrumentation" comment above `groupEntered` for
    // how the caller derives this from `session.groups.lastOption`. Lets
    // the Requests tab nest a request under the same group Gatling's own
    // report shows it under.
    if (group.nonEmpty) {
      spanBuilder.setAttribute("group", group)
    }

    // --- Text attributes: per-attribute caps under ONE shared ceiling ---
    // Each payload-derived attribute is trimmed to the cap it already had
    // before this card (never longer than the pre-card `take(...)`, never
    // shorter than it either) and charged to one shared allowance, spent in
    // this order: headers, response body, request body. The identity at
    // SpanAttributeBudgetChars is what makes the order safe — the three
    // attributes ahead of the request body cannot exhaust the allowance
    // between them, so none of them is ever cut by the ceiling and the
    // request body still keeps RequestBodyFloorChars in the worst case.
    var spanAttributeBudget = SpanAttributeBudgetChars
    def capTo(value: String, cap: Int): String =
      if (value == null) ""
      else if (value.length <= cap) value
      else value.substring(0, cap)
    def spendBudget(value: String, cap: Int): String = {
      val allowance = if (cap < spanAttributeBudget) cap else spanAttributeBudget
      val slice = capTo(value, allowance)
      spanAttributeBudget -= slice.length
      slice
    }

    // Headers first: they are small, bounded by the wire, and are what makes
    // a 4xx diagnosable.
    val cappedRequestHeaders = spendBudget(requestHeaders, HeaderAttributeCapChars)
    if (cappedRequestHeaders.nonEmpty) {
      spanBuilder.setAttribute("request.headers", cappedRequestHeaders)
    }
    val cappedResponseHeaders = spendBudget(responseHeaders, HeaderAttributeCapChars)
    if (cappedResponseHeaders.nonEmpty) {
      spanBuilder.setAttribute("response.headers", cappedResponseHeaders)
    }
    // Run-aggregate validators (Phase 5) need successful responses too, not
    // only errors — so the response body rides every span, ahead of the
    // opt-in request body: it is the attribute the error event republishes
    // and the one the run analysis is built from.
    val cappedResponseBody = spendBudget(responseBody, ResponseBodyCapChars)
    if (cappedResponseBody.nonEmpty) {
      spanBuilder.setAttribute("response.body", cappedResponseBody)
    }
    // Mirror the request body so debugging a failing assertion / 4xx /
    // unexpected response actually shows what we sent. Empty whenever the
    // project has not opted into body capture (or the response was not
    // sampled) — the generated protocol seam decides that, not this method.
    val cappedRequestBody = spendBudget(requestBody, RequestBodyCapChars)
    if (cappedRequestBody.nonEmpty) {
      spanBuilder.setAttribute("request.body", cappedRequestBody)
    }
    // Not a span attribute: it rides the span STATUS and the error event.
    // Capped here so the wire ceiling holds whatever the caller passes.
    val cappedErrorMessage = capTo(errorMessage, ErrorMessageCapChars)

    val span = spanBuilder.startSpan()

    if (isError) {
      span.setStatus(StatusCode.ERROR, cappedErrorMessage)
      // The event reuses the slices already charged above — a second,
      // independently-truncated copy of the response body was what pushed a
      // failing span past ~38 KB.
      span.addEvent("error", Attributes.builder()
        .put("error.message", cappedErrorMessage)
        .put("response.body", cappedResponseBody)
        .build()
      )
      errorCounter.add(1, Attributes.builder()
        .put("request.name", normalizedName)
        .put("http.status_code", httpStatus.toLong)
        .build()
      )
    }

    // --- Ledger: the step, the attribution, and the span's outcome ---
    //
    // CLOSE the step this response belongs to, and tell this VU's ledger
    // whether the wire already called it a failure. The open multiset is what
    // `settleOpenLocked` turns into no-response increments, so without the
    // close every step would look like a request that got no response and the
    // limb would count the whole run; the KO tally is what stops
    // `observeLocked` charging a 4xx/5xx to the check limb as well.
    //
    // Then the span. A KO response is decided on the wire and its span ends
    // below, at once. Any other response can still be re-decided by an unmet
    // check, which this ledger learns only at the VU's next observation, so
    // its span is HELD: the span held before it ends as it is first (a newer
    // response was recorded), and this one is held in its place, in the same
    // monitor acquisition that makes it the request `answered*` names.
    var held = false
    try {
      val ledger = ledgerFor(userId)
      ledger.synchronized {
        if (isError) ledger.kos += 1L
        closeLocked(ledger, StepKey(requestName, method, group))
        // This build got its response: it is no longer in flight.
        if (build ne null) ledger.buildsInFlight.remove(build)
        ledger.answeredName = requestName
        ledger.answeredMethod = method
        ledger.answeredGroup = group
        ledger.answeredStatus = httpStatus
        // The end of the latest response, which the next think-time site is
        // measured from (P1b).
        ledger.lastResponseEndMs = math.max(ledger.lastResponseEndMs, endMs)
        endHeldLocked(ledger)
        if (!isError) {
          holdLocked(ledger, span, endMs, cappedResponseBody)
          held = true
        }
      }
    } catch { case _: Exception => () }

    // A KO span, or one the ledger could not take, ends here at its own end.
    if (!held) span.end(endMs, TimeUnit.MILLISECONDS)

    // --- Native metrics (redundant baseline alongside spanmetrics) ---
    val baseAttrsBuilder = Attributes.builder()
      .put("request.name", normalizedName)
      .put("http.method", method)
      .put("http.status_code", httpStatus.toLong)
    // Tagging the shared request-count/duration attrs with `group` (when
    // present) is what lets Prometheus expose
    // loadcraft_http_duration{group="..."} so the UI can nest requests
    // under the same group Gatling's own report groups them under. Always
    // uses the RETURN VALUE of the final `.put` (never a bare-statement
    // call on the builder) so this is correct whether AttributesBuilder
    // mutates in place or returns a fresh builder per call.
    val attrs =
      if (group.nonEmpty) baseAttrsBuilder.put("group", group).build()
      else baseAttrsBuilder.build()
    requestCounter.add(1, attrs)
    responseTimeHistogram.record(durationMs, attrs)
  }

  /**
   * Graceful shutdown — flush pending spans and metrics.
   * Called from JVM shutdown hook in generated simulations.
   *
   * The ledger drain runs FIRST: closing the SDK flushes what has been
   * recorded, so a limb settled or a held span ended after the close would
   * never reach the collector. This is the only place the SDK is closed (its
   * own JVM hook is disabled where it is built), so the close is in
   * `finally`: whatever the drain throws, what was recorded is flushed.
   */
  def shutdown(): Unit = {
    try drainLedgers()
    finally sdk match {
      case closeable: java.io.Closeable => closeable.close()
      case _ => ()
    }
  }
}

