    // auth registration for the same name (e.g. a placeholder
    // Authorization value) — skip any default whose name this
    // protocol already computes above.
    val computedAuthHeaderNames: Set[String] = Set("x-store-api-key")
    val withHeaders = Environment.defaultHeaders.foldLeft(base) { case (protocol, (name, value)) =>
      if (computedAuthHeaderNames.contains(name.toLowerCase)) protocol else protocol.header(name, value)
    }
    // OTel request seam (mirrors the flat SIMULATION_TEMPLATE, the generator):
    // every request rides this single protocol, so per-request metrics are
    // captured centrally — requestStarted on send, one record per response in
    // transformResponse. No per-step recorder (avoids double count). The pair
    // is also what settles the no-response and unmet-check limbs: `.sign`
    // opens a step in the
    // plugin's per-VU ledger, `.transformResponse` records the response
    // against it, and the next `.sign` decides which limb the step belonged to.
    withHeaders
      .sign { (request, session) =>
        // `.sign` is the ONE hook Gatling 3.14.5 runs BEFORE the request leaves
        // the client, so it is the only seam a request that never gets a response
        // can be seen from. It opens this VU's step in the plugin's ledger and,
        // with `isFailed`, settles the step before it. The name is derived by the
        // plugin so this seam and `.transformResponse` below open and record one
        // and the same metric series; the signature calculator is the identity
        // of the request's BUILD: every write of it (a retry on a new
        // connection included) carries the same one, so the step opens once
        io.loadcraft.gatling.LoadCraftOTelPlugin.requestStarted(
          session.userId,
          session.isFailed,
          request.getName,
          request.getMethod.toString,
          request.getUri.getPath,
          session.groups.lastOption.getOrElse(""),
          request.getSignatureCalculator
        )
        io.gatling.commons.validation.Success(request)
      }
      .transformResponse { (response, session) =>
        try {
          val respBody = try { response.body.string } catch { case _: Exception => "" }
          // Capturing the request body means reflection
          // plus a full materialization of the body on EVERY response,
          // paid for out of the load budget. Opt-in per project
          // (gatling_projects.capture_request_bodies); OFF here.
          val reqBody = ""
          val reqHeaders = io.loadcraft.gatling.LoadCraftOTelPlugin.extractHeaders(response.request.getHeaders, otelProtectedHeaderNames)
          val respHeaders = io.loadcraft.gatling.LoadCraftOTelPlugin.extractHeaders(response.headers, otelProtectedHeaderNames)
          val errorMessage = if (response.status.code() >= 400) respBody.take(256) else ""
          // Prefer the Gatling request name (template-stable) over the
          // resolved URI path so /api/products/1 and /api/products/2
          // aggregate under one metric name, not one per id. The rule lives
          // in the plugin, so the `.sign` seam opens the same metric series
          val effectiveName = io.loadcraft.gatling.LoadCraftOTelPlugin.effectiveRequestName(
            response.request.getName,
            response.request.getMethod.toString,
            response.request.getUri.getPath
