          // Current (innermost) enclosing group() block, if any — session.groups
          // is outermost-first (Gatling's Session#groups, NOT groupHierarchy —
          // that accessor does not exist), so .lastOption is the group this
          // request executes inside. Tags the span + request metrics so the
          // Requests tab can nest requests under the same group Gatling's own
          // report groups them under.
          val grp = session.groups.lastOption.getOrElse("")
          io.loadcraft.gatling.LoadCraftOTelPlugin.recordRequest(
            userId = session.userId,
            requestName = effectiveName,
            requestUrl = response.request.getUri.toString,
            method = response.request.getMethod.toString,
            httpStatus = response.status.code(),
            startMs = response.startTimestamp,
            endMs = response.endTimestamp,
            responseBody = respBody,
            errorMessage = errorMessage,
            requestBody = reqBody,
            requestHeaders = reqHeaders,
            responseHeaders = respHeaders,
            group = grp,
            build = response.request.getSignatureCalculator
          )
        } catch {
          case _: Exception => // skip metrics for this request
        }
        response
      }
  }

  // Removes protocol-hoisted headers from a request that never sent them in the
  // source flow (e.g. a pre-auth login), keeping its effective headers
  // byte-faithful. The DSL cannot un-set a protocol default header; the sign
  // hook runs on the fully built request, where removal is possible.
  //
  // IT OPENS THE STEP ITSELF, and the plugin de-duplicates by build identity.
  // Gatling 3.13.x resolved ONE signature calculator
  // (`commonAttributes.signatureCalculator.orElse(httpProtocol.requestPart.signatureCalculator)`):
  // a request-level `.sign` REPLACED the protocol-level one, so a wrapper that
  // only stripped headers left its step unopened in the per-VU ledger and a
  // timeout on it settled as nothing. Gatling 3.15.x keeps a LIST and folds
  // `protocol ::: request` over the request, so BOTH seams run and this call
  // reaches requestStarted a second time for the same wire request — which
  // used to leave a phantom no_response on the login at the end of every VU.
  // Passing the request's signature calculator, the one fold function both
  // seams see for this build, lets the plugin open the step exactly once
  // under either resolution. The step this typically wraps is
  // the pre-auth login, exactly the request a degraded target stops answering
  // first; the session is threaded through because the ledger is per VU.
  def stripHeaders(rb: HttpRequestBuilder, names: Seq[String]): HttpRequestBuilder =
    rb.sign { (request, session) =>
      io.loadcraft.gatling.LoadCraftOTelPlugin.requestStarted(
        session.userId,
        session.isFailed,
        request.getName,
        request.getMethod.toString,
        request.getUri.getPath,
        session.groups.lastOption.getOrElse(""),
        request.getSignatureCalculator
      )
      names.foreach(n => request.getHeaders.remove(n))
      io.gatling.commons.validation.Success(request)
    }
}
